/// </summary>
public enum SunSpecModel64411Regen : ushort
{
    /// <summary>
    /// Regen Off
    /// </summary>
    OFF = 0,

    /// <summary>
    /// Regen On
    /// </summary>
    ON = 1,
}

/// <summary>
/// Start/Stop the AC Profile
/// </summary>
public enum SunSpecModel64411EnaProf : ushort
{
    /// <summary>
    /// Stop Profile
    /// </summary>
    STOP = 0,

    /// <summary>
    /// Start Profile Immediately
    /// </summary>
    START = 1,

    /// <summary>
    /// Start Profile via External Trigger Signal
    /// </summary>
    TRIGGER = 2,
}

/// <summary>
/// Result of last profile operation.
/// </summary>
public enum SunSpecModel64411ProfRslt : ushort
{
    /// <summary>
    /// Profile update in progress.
    /// </summary>
    IN_PROGRESS = 0,

    /// <summary>
    /// Profile update completed successfully.
    /// </summary>
    COMPLETED = 1,

    /// <summary>
    /// Profile update failed.
    /// </summary>
    FAILED = 2,
}
